        rightArmJoint.addRotX(blend * -(Math.cos((double)(limbSwing * speed) + -0.8 + rightArmOffset) * 0.7 * (double)globalDegree - 1.0) * (double)limbSwingAmount);
        rightArmJoint.addRotY(blend * -(Math.cos((double)(limbSwing * speed) + -0.8 + rightArmOffset) * 0.4 * (double)globalDegree + 0.5) * (double)limbSwingAmount);
        rightArmJoint.addRotZ(blend * -(Math.cos((double)(limbSwing * speed) + -0.8 + rightArmOffset) * -0.6 * (double)globalDegree - (double)0.2f) * (double)limbSwingAmount);
        rightForeArm.addRotX(blend * (Math.cos((double)(limbSwing * speed) - 1.65 + rightArmOffset) * 0.5 * (double)globalDegree - 0.87) * (double)limbSwingAmount);
        rightForeArm.addRotX(blend * this.poweredWave(limbSwing, speed, 2.341592788696289, 3.0) * 0.5 * (double)globalHeight * (double)limbSwingAmount);
        rightForeArm.addRotZ(blend * (Math.cos((double)(limbSwing * speed) - 0.3 + rightArmOffset) * -0.7 * (double)globalDegree - 0.2) * (double)limbSwingAmount);
        rightHand.addRotX(blend * (Math.cos((double)(limbSwing * speed) + 4.5 + rightArmOffset) * -0.8 * (double)globalDegree - 0.8) * (double)limbSwingAmount);
        rightHand.addRotY(blend * -(Math.cos((double)(limbSwing * speed) + 4.5 + rightArmOffset) * 1.0 * (double)globalDegree + 0.5) * (double)limbSwingAmount);
        Bone tail1 = this.getMowzieBone("tail1_day");
        Bone tail2 = this.getMowzieBone("tail2_day");
        Bone tail3 = this.getMowzieBone("tail3_day");
        tail1.addRotX(blend * (Math.cos((double)(limbSwing * speed) + 0.9) * (double)0.3f * (double)globalHeight) * (double)limbSwingAmount);
        tail2.addRotX(blend * (Math.cos((double)(limbSwing * speed) + 0.9 - 1.0) * (double)0.2f * (double)globalHeight) * (double)limbSwingAmount);
        tail3.addRotX(blend * (Math.cos((double)(limbSwing * speed) + 0.9 - 2.0) * (double)0.2f * (double)globalHeight) * (double)limbSwingAmount);
    
